1	package clinical
2	
3	// scopeKey 是整类覆盖的定位键：某次就诊 + 某个记录类别（诊断/医嘱）。
4	type scopeKey struct {
5		encounterID ID
6		category    string
7	}
8	
9	// grantCoverage 是授权范围被归一化后的“覆盖含义”，是接收方查阅与内部使用者
10	// 创建交换共用的唯一判定来源：两处对同一条授权“覆盖什么”的理解必须一致，
11	// 不能各自维护一套判断。
12	//
13	// 覆盖由两个互不串用的维度组成：
14	//
15	//   - whole：整类范围。某个“就诊+类别”一旦在其中，该范围下的全部已生效记录
16	//     都被覆盖，包括授权建立之后才生效的记录。
17	//   - selected：限定范围。只覆盖明确选中的记录标识；键记录该选择声明的
18	//     “就诊+类别”，用于把限定覆盖严格约束在所声明的就诊与类别内。被选记录
19	//     更正后仍按记录标识覆盖它的当前版本；同类其他记录以及后来新增的记录
20	//     不会因此获得授权。
21	//
22	// 可由多条授权合并而成（接收方查阅合并该患者、该接收方的所有当前有效授权），
23	// 也可只装一条绑定授权（创建交换时不能借用其他授权补足）。
24	type grantCoverage struct {
25		whole          map[scopeKey]bool
26		selected       map[ID]scopeKey
27		selectedScopes map[scopeKey]bool
28	}
29	
30	func newGrantCoverage() *grantCoverage {
31		return &grantCoverage{
32			whole:          map[scopeKey]bool{},
33			selected:       map[ID]scopeKey{},
34			selectedScopes: map[scopeKey]bool{},
35		}
36	}
37	
38	// add 把一条授权的整类范围与限定范围并入当前覆盖。调用方负责只并入满足身份
39	// （同一患者、同一接收方）且在核对时刻有效的授权；这里只解释范围本身。
40	func (c *grantCoverage) add(a *Authorization) {
41		for _, sc := range a.Scopes {
42			c.whole[scopeKey{encounterID: sc.EncounterID, category: sc.Category}] = true
43		}
44		for _, sel := range a.Selections {
45			k := scopeKey{encounterID: sel.EncounterID, category: sel.Category}
46			// 重复选择同一记录只算一次；保留其声明的就诊+类别。
47			c.selected[sel.RecordID] = k
48			c.selectedScopes[k] = true
49		}
50	}
51	
52	// coversScope 报告整类范围是否覆盖某次就诊下某个类别。
53	func (c *grantCoverage) coversScope(encounterID ID, category string) bool {
54		return c.whole[scopeKey{encounterID: encounterID, category: category}]
55	}
56	
57	// coversRequest 报告覆盖是否触及所请求的“就诊+类别”：存在覆盖它的整类范围，
58	// 或至少有一条限定选择明确声明属于该就诊与类别。用于区分“有授权但当前没有
59	// 生效记录（返回空集合）”与“没有任何授权覆盖（拒绝）”。
60	func (c *grantCoverage) coversRequest(encounterID ID, category string) bool {
61		k := scopeKey{encounterID: encounterID, category: category}
62		return c.whole[k] || c.selectedScopes[k]
63	}
64	
65	// coversRecord 报告某条具体记录是否被覆盖：整类范围按记录实际的就诊+类别
66	// 覆盖；限定范围只覆盖明确选中的记录标识，且该选择声明的就诊+类别必须与
67	// 记录实际所在一致（授权建立时已校验，此处再保证覆盖关系不会串到其他就诊
68	// 或类别）。草稿或无生效版本的记录由调用方另行排除。
69	func (c *grantCoverage) coversRecord(r *Record) bool {
70		k := scopeKey{encounterID: r.EncounterID, category: r.Category}
71		if c.whole[k] {
72			return true
73		}
74		declared, ok := c.selected[r.ID]
75		return ok && declared == k
76	}
77

